mapper.insert:

	SELECT NVL(MAX(submit_test_no), 0) + 1
	FROM submit_test

INSERT INTO submit_test
	   (
			submit_test_no
			, homework_no
			, member_id
			, answer_state
			, total_score
			, answer_percent
			, submit_date
	   )
VALUES (
			#{submitTestNo}
			, #{homeworkNo}
			, #{memberId}
			, 'C301'
			, #{totalScore}
			, #{answerPercent}
			, sysdate
		)

mapper.select:
SELECT *	FROM (select rownum rn, tb.* from (

	select *
	from submit_test a join member b on(a.member_id = b.member_id)
	where homework_no = #{homeworkNo}
	order by submit_test_no DESC

) tb)	WHERE rn BETWEEN #{startNo} AND #{endNo}

select count(*)
from submit_test
where homework_no = #{homeworkNo}
